:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #183a36;
  background: #e9f0e8;
}
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #f8f3df 0, #e9f0e8 70%); }
.booking-card { width: min(100%, 540px); padding: 32px; border: 1px solid #d5e2d7; border-radius: 24px; background: #fffefa; box-shadow: 0 18px 55px #183a3617; }
.eyebrow { margin: 0 0 8px; color: #648578; font-weight: 750; font-size: .8rem; letter-spacing: .11em; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.4rem); line-height: 1.15; }
.intro { margin: 10px 0 24px; color: #60766f; }
.legend { display: flex; flex-wrap: wrap; gap: 12px 20px; padding: 14px 0 18px; color: #50665f; font-size: .9rem; }
.legend span { display: inline-flex; align-items: center; gap: 8px; }
.legend-seat { width: 19px; height: 19px; border-radius: 6px; display: inline-block; border: 1px solid #b8cec1; }
.legend-seat.available { background: #fffefa; }
.legend-seat.selected { background: #267b66; border-color: #267b66; }
.legend-seat.booked { background: #dce4df; border-color: #dce4df; }
.bus { max-width: 360px; margin: 0 auto 24px; padding: 12px 16px 18px; border: 2px solid #d5e2d7; border-radius: 44px 44px 20px 20px; background: #f5f8f2; }
.driver { height: 34px; display: flex; align-items: center; justify-content: space-between; padding: 0 10px; color: #83968d; font-size: .72rem; font-weight: 750; letter-spacing: .1em; }
.wheel { color: #267b66; font-size: 1.3rem; }
.seat-map { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)) 22px repeat(2, minmax(0, 1fr)); gap: 8px 7px; }
.seat, .aisle { min-width: 0; height: 38px; }
.seat { border: 1px solid #b8cec1; border-radius: 9px 9px 7px 7px; background: #fffefa; color: #285247; font: inherit; font-size: .86rem; font-weight: 700; cursor: pointer; transition: background .15s, color .15s, transform .15s, box-shadow .15s; }
.seat:hover:not(:disabled) { background: #e3f1e9; transform: translateY(-1px); }
.seat:active:not(:disabled) { transform: scale(.96); }
.seat:focus-visible { outline: 3px solid #dda94a; outline-offset: 2px; z-index: 1; }
.seat[aria-pressed="true"] { background: #267b66; border-color: #267b66; color: white; }
.seat:disabled { background: #dce4df; border-color: #dce4df; color: #82918a; cursor: not-allowed; text-decoration: line-through; }
.aisle { grid-column: 3; grid-row: 1 / span 10; }
.summary { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding: 20px; border-radius: 16px; background: #f5f8f2; }
h2 { margin: 0 0 7px; font-size: 1rem; }
#chosen-seats { margin: 0; color: #405b52; overflow-wrap: anywhere; }
.discount-note { margin: 7px 0 0; color: #648578; font-size: .88rem; }
.total-block { flex: 0 0 auto; text-align: right; }
.total-block span { display: block; color: #648578; font-size: .85rem; }
.total-block strong { font-size: 1.7rem; }
.message { min-height: 1.4em; margin: 12px 4px 0; color: #a24a36; font-size: .9rem; }
@media (max-width: 420px) { body { padding: 16px 10px; } .booking-card { padding: 24px 18px; border-radius: 20px; } .bus { padding-inline: 10px; } .seat-map { gap: 7px 5px; grid-template-columns: repeat(2, minmax(0, 1fr)) 16px repeat(2, minmax(0, 1fr)); } .seat { height: 36px; font-size: .8rem; } .aisle { grid-column: 3; } .summary { padding: 16px 14px; } }

const seatMap = document.getElementById('seat-map');
const chosenSeats = document.getElementById('chosen-seats');
const totalPrice = document.getElementById('total-price');
const discountNote = document.getElementById('discount-note');
const message = document.getElementById('selection-message');
const booked = new Set(['1B', '3D', '5A', '7C', '9B']);
const selected = new Set();
const columns = ['A', 'B', 'C', 'D'];

for (let row = 1; row <= 10; row++) {
  columns.forEach((column, index) => {
    const code = `${row}${column}`;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'seat';
    button.textContent = code;
    button.setAttribute('aria-label', `Seat ${code}${booked.has(code) ? ', booked' : ', available'}`);
    button.setAttribute('aria-pressed', 'false');
    if (booked.has(code)) {
      button.disabled = true;
      button.setAttribute('aria-label', `Seat ${code}, booked`);
    }
    button.addEventListener('click', () => {
      message.textContent = '';
      if (selected.has(code)) selected.delete(code);
      else if (selected.size < 4) selected.add(code);
      else {
        message.textContent = 'You can choose up to four seats. Remove a seat to choose another.';
        return;
      }
      button.setAttribute('aria-pressed', String(selected.has(code)));
      updateSummary();
    });
    seatMap.append(button);
    if (index === 1) {
      const aisle = document.createElement('span');
      aisle.className = 'aisle';
      aisle.setAttribute('aria-hidden', 'true');
      seatMap.append(aisle);
    }
  });
}

function updateSummary() {
  const seats = [...selected].sort((a, b) => {
    const rowDiff = Number.parseInt(a, 10) - Number.parseInt(b, 10);
    return rowDiff || a.slice(-1).localeCompare(b.slice(-1));
  });
  chosenSeats.textContent = seats.length ? seats.join(', ') : 'No seats selected';
  const discounted = seats.length === 4;
  const total = seats.length * 12 * (discounted ? 0.9 : 1);
  totalPrice.textContent = `$${total.toFixed(2).replace(/\.00$/, '')}`;
  discountNote.textContent = discounted ? '10% four-seat discount applied' : '$12 per seat';
}
